begin;
insert into auth.users(id,email) values ('00000000-0000-4000-8000-000000000001','webhook-admin@test.invalid'),('00000000-0000-4000-8000-000000000002','webhook-member@test.invalid'),('00000000-0000-4000-8000-000000000003','webhook-other@test.invalid');
insert into public.organizations(id,name) values ('10000000-0000-4000-8000-000000000001','Webhooks A'),('10000000-0000-4000-8000-000000000002','Webhooks B');
insert into public.memberships(organization_id,user_id,role) values
('10000000-0000-4000-8000-000000000001','00000000-0000-4000-8000-000000000001','admin'),
('10000000-0000-4000-8000-000000000001','00000000-0000-4000-8000-000000000002','member'),
('10000000-0000-4000-8000-000000000002','00000000-0000-4000-8000-000000000003','admin');
insert into public.lines(id,organization_id,phone_number,voice_enabled,sms_enabled) values ('20000000-0000-4000-8000-000000000001','10000000-0000-4000-8000-000000000001','+33102030405',true,true);
insert into public.conversations(id,organization_id,line_id,remote_number) values ('30000000-0000-4000-8000-000000000001','10000000-0000-4000-8000-000000000001','20000000-0000-4000-8000-000000000001','+33601020304');
do $$
declare org uuid:='10000000-0000-4000-8000-000000000001'; actor uuid:='00000000-0000-4000-8000-000000000001'; member uuid:='00000000-0000-4000-8000-000000000002'; endpoint uuid:=gen_random_uuid(); v_message_id uuid; call_id uuid; event_id uuid; jobs jsonb; job jsonb; result jsonb; n integer;
 input jsonb:='{"description":"CRM","url":"https://example.com/hook","events":["sms.received","sms.sent","sms.delivered","sms.failed","call.received","call.started","call.connected","call.ended","call.missed","voicemail.received","user.status_changed","user.reachability_changed"],"secretCiphertext":"encrypted-test"}';
begin
 assert not has_table_privilege('authenticated','public.webhook_events','select'), 'Event content is private';
 assert not has_table_privilege('onoff_mcp','public.webhook_endpoints','select'), 'Secrets private to server';
 assert not exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname in ('manage_customer_webhook','claim_customer_webhooks','finish_customer_webhook','refresh_webhook_reachability','prune_customer_webhooks') and (has_function_privilege('authenticated',p.oid,'execute') or has_function_privilege('anon',p.oid,'execute') or has_function_privilege('onoff_mcp',p.oid,'execute'))), 'RPCs service only';
 begin perform public.manage_customer_webhook(org,member,'create',endpoint,input);raise exception 'Non-admin created endpoint';exception when insufficient_privilege then null;end;
 begin perform public.manage_customer_webhook(org,'00000000-0000-4000-8000-000000000003','create',endpoint,input);raise exception 'Foreign admin created endpoint';exception when insufficient_privilege then null;end;
 result:=public.manage_customer_webhook(org,actor,'create',endpoint,input);
 assert result->>'secret_ciphertext' is null, 'Management never returns ciphertext';
 perform public.manage_customer_webhook('10000000-0000-4000-8000-000000000002','00000000-0000-4000-8000-000000000003','create',gen_random_uuid(),input);
 begin perform public.manage_customer_webhook('10000000-0000-4000-8000-000000000002','00000000-0000-4000-8000-000000000003','delete',endpoint);raise exception 'Foreign endpoint deleted';exception when no_data_found then null;end;
 insert into public.messages(organization_id,conversation_id,direction,body,status,provider_message_sid) values(org,'30000000-0000-4000-8000-000000000001','inbound','Bonjour','received','SM11111111111111111111111111111111') returning messages.id into v_message_id;
 update public.messages set status='received' where messages.id=v_message_id;
 assert (select count(*) from public.webhook_events where event_type='sms.received')=1, 'Duplicate status does not emit again';
 assert (select count(*) from public.webhook_deliveries)=1, 'No cross-tenant delivery';
 assert (select payload#>>'{data,body}' from public.webhook_events where event_type='sms.received')='Bonjour', 'Documented content present';
 assert not exists(select 1 from public.webhook_events where payload::text like '%SM111%'), 'No provider SID';
 begin insert into public.messages(organization_id,conversation_id,direction,body,status) values(org,'30000000-0000-4000-8000-000000000001','inbound','Rolled back','received');raise exception 'rollback';exception when raise_exception then null;end;
 assert (select count(*) from public.webhook_events)=1, 'Event and message roll back together';
 insert into public.messages(organization_id,conversation_id,direction,body,status) values(org,'30000000-0000-4000-8000-000000000001','outbound','Salut','submitting') returning messages.id into v_message_id;
 update public.messages set status='sent' where messages.id=v_message_id;
 update public.messages set status='delivered' where messages.id=v_message_id;
 assert (select count(*) from public.webhook_events where event_type in ('sms.sent','sms.delivered'))=2, 'Outgoing lifecycle';
 insert into public.calls(organization_id,line_id,direction,remote_number,status) values(org,'20000000-0000-4000-8000-000000000001','inbound','+33601020304','ringing') returning calls.id into call_id;
 assert (select count(*) from public.webhook_events where event_type='call.received')=1, 'Inbound event';
 assert (select count(*) from public.webhook_events where event_type='call.connected')=0, 'Ringing/IVR not connected';
 update public.calls set status='answered',answered_at=now() where calls.id=call_id;
 update public.calls set answered_at=answered_at where calls.id=call_id;
 update public.calls set status='completed',ended_at=now() where calls.id=call_id;
 update public.calls set ended_at=ended_at where calls.id=call_id;
 assert (select count(*) from public.webhook_events where event_type='call.connected')=1, 'Single connected event';
 assert (select count(*) from public.webhook_events where event_type='call.ended')=1, 'Single ended event';
 assert (select count(*) from public.webhook_events where event_type='call.missed')=0, 'Answered call not missed';
 insert into public.calls(organization_id,line_id,direction,remote_number,status,ended_at) values(org,'20000000-0000-4000-8000-000000000001','inbound','+33601020304','failed',now());
 assert (select count(*) from public.webhook_events where event_type='call.missed')=1, 'Any unanswered inbound terminal outcome is missed';
 insert into public.voice_voicemails(organization_id,call_id,recording_sid,duration) values(org,call_id,'RE11111111111111111111111111111111',8);
 assert (select count(*) from public.webhook_events where event_type='voicemail.received')=1, 'Voicemail event';
 update public.memberships set role='admin' where organization_id=org and user_id=member;
 assert (select count(*) from public.webhook_events where event_type='user.status_changed')=1, 'Role transition';
 perform public.refresh_webhook_reachability();
 insert into public.devices(organization_id,user_id,platform,label,voice_identity,voice_registered_at) values(org,member,'web','Test','webhook_test',now());
 perform public.refresh_webhook_reachability();perform public.refresh_webhook_reachability();
 assert (select count(*) from public.webhook_events where event_type='user.reachability_changed')=1, 'Reachability changes, no heartbeats';
 update public.devices set voice_registered_at=now()-interval '100 seconds' where voice_identity='webhook_test';
 perform public.refresh_webhook_reachability();
 assert (select count(*) from public.webhook_events where event_type='user.reachability_changed')=2, 'Silent web expiry';
 jobs:=public.claim_customer_webhooks(1);job:=jobs->0;
 assert jsonb_array_length(jobs)=1 and (job->>'attempt')::int=1, 'Claim one job';
 assert (public.claim_customer_webhooks(1)->0->>'id')<>job->>'id', 'Live lease not claimed twice';
 assert not public.finish_customer_webhook((job->>'id')::uuid,gen_random_uuid(),204,null), 'Wrong lease cannot acknowledge';
 assert public.finish_customer_webhook((job->>'id')::uuid,(job->>'leaseToken')::uuid,503,'http_503'), 'Failure scheduled';
 assert (select status='pending' and attempts=1 and next_attempt_at>now() from public.webhook_deliveries where webhook_deliveries.id=(job->>'id')::uuid), 'Backoff persisted';
 update public.webhook_deliveries set status='delivered' where webhook_deliveries.id<>(job->>'id')::uuid;
 for n in 2..8 loop
   update public.webhook_deliveries set next_attempt_at=now() where webhook_deliveries.id=(job->>'id')::uuid;
   job:=public.claim_customer_webhooks(1)->0;
   perform public.finish_customer_webhook((job->>'id')::uuid,(job->>'leaseToken')::uuid,302,'http_302');
 end loop;
 assert (select status='failed' and attempts=8 from public.webhook_deliveries where webhook_deliveries.id=(job->>'id')::uuid), 'Stops after eight failures';
 event_id:=(job#>>'{payload,id}')::uuid;
 result:=public.manage_customer_webhook(org,actor,'replay',endpoint,jsonb_build_object('deliveryId',job->>'id'));
 job:=public.claim_customer_webhooks(1)->0;
 assert job#>>'{payload,id}'=event_id::text, 'Replay preserves event id';
 update public.webhook_deliveries set locked_until=now()-interval '1 second' where webhook_deliveries.id=(job->>'id')::uuid;
 jobs:=public.claim_customer_webhooks(1);
 assert jobs->0->>'id'=job->>'id' and jobs->0->>'leaseToken'<>job->>'leaseToken', 'Crash resumes with new lease';
 assert not public.finish_customer_webhook((job->>'id')::uuid,(job->>'leaseToken')::uuid,204,null), 'Expired worker cannot finish reclaimed job';
 job:=jobs->0;
 assert public.finish_customer_webhook((job->>'id')::uuid,(job->>'leaseToken')::uuid,204,null), 'Current worker delivers';
 result:=public.manage_customer_webhook(org,actor,'test',endpoint);
 assert result->>'eventId' is not null,'Test queued';
 begin perform public.manage_customer_webhook(org,actor,'test',endpoint);raise exception 'Test flood';exception when program_limit_exceeded then null;end;
 perform public.manage_customer_webhook(org,actor,'enabled',endpoint,'{"enabled":false}');
 assert not exists(select 1 from public.webhook_deliveries where endpoint_id=endpoint and status in ('sending','pending')), 'Pause cancels pending jobs';
 perform public.manage_customer_webhook(org,actor,'enabled',endpoint,'{"enabled":true}');
 update public.memberships set status='suspended' where organization_id=org and user_id=actor;
 assert jsonb_array_length(public.claim_customer_webhooks(20))=0,'Revoked creator cannot deliver';
 update public.webhook_events set created_at=now()-interval '8 days';perform public.prune_customer_webhooks();
 assert (select count(*) from public.webhook_events)=0 and (select count(*) from public.webhook_deliveries)=0, 'Retention removes payload and delivery';
end $$;
select 'ok - Customer webhook tenant isolation, atomic events, deduplication, presence, leases, retries, revocation and retention';
rollback;
